async function mineOnce(namePattern) {
  const locs = sdk.getNearbyLocs();
  const rock = locs.filter(l => namePattern.test(l.name) && l.distance <= 5).sort((a,b)=>a.distance-b.distance)[0];
  if (!rock) return null;
  const mineOpt = rock.optionsWithIndex.find(o => /^mine$/i.test(o.text));
  const beforeXp = sdk.getSkillXp("Mining");
  const beforeCount = sdk.getInventory().length;
  await sdk.sendInteractLoc(rock.x, rock.z, rock.id, mineOpt.opIndex);
  // wait until xp changes or timeout
  const start = Date.now();
  while (Date.now() - start < 8000) {
    await new Promise(r => setTimeout(r, 300));
    if (sdk.getState().dialog?.isOpen) { await bot.dismissBlockingUI(); }
    const xp = sdk.getSkillXp("Mining");
    if (xp > beforeXp) {
      return { gained: xp - beforeXp, ms: Date.now() - start, rockName: rock.name };
    }
  }
  return { gained: 0, ms: Date.now() - start, rockName: rock.name, timedOut: true };
}

