async function killAndLoot() {
  const before = sdk.getState();
  const target = before.nearbyNpcs.find(n => /^chicken$/i.test(n.name));
  if (!target) return { error: "no chicken nearby" };
  await bot.attackNpc(/^chicken$/i);
  // poll until that npc index is gone or dead, max ~5s
  let dead = false;
  for (let i = 0; i < 25; i++) {
    const s = sdk.getState();
    const c = s.nearbyNpcs.find(n => n.index === target.index);
    if (!c) { dead = true; break; }
    await new Promise(r => setTimeout(r, 200));
  }
  await bot.dismissBlockingUI();
  const s2 = sdk.getState();
  const raw = s2.groundItems.find(g => /^raw chicken$/i.test(g.name) && g.distance <= 3);
  let picked = null;
  if (raw) {
    picked = await bot.pickupItem(/^raw chicken$/i);
  }
  return { dead, ground: s2.groundItems, picked };
}
